package com.aicharacter.v3;
/** Muscle work raises metabolic demand; respiration and circulation determine usable supply and recovery. */
public final class CardioMetabolicEngine{private CardioMetabolicEngine(){}
 public static void advance(WorldState s,double dt){if(s==null||dt<=0)return;if(s.circulation==null)s.circulation=new CirculationState();if(s.metabolism==null)s.metabolism=new MetabolismState();double work=s.girlTravel!=null&&s.girlTravel.active?Math.min(1,s.girlTravel.lastSpeed/92.0):0;double fatigue=s.musculoskeletal==null?0:s.musculoskeletal.legFatigue;double demand=Math.min(1,.16+work*.62+fatigue*.16);s.metabolism.demand=follow(s.metabolism.demand,demand,dt,2.5);double respiratory=s.respiration==null?1:Math.max(.12,1-s.respiration.strain);s.circulation.cardiacDrive=follow(s.circulation.cardiacDrive,Math.min(1,.25+demand*.7),dt,3.0);s.circulation.perfusion=Math.max(.2,Math.min(1,.55+s.circulation.cardiacDrive*.5));s.circulation.oxygenDelivery=Math.max(.08,Math.min(1,respiratory*s.circulation.perfusion));double shortage=Math.max(0,s.metabolism.demand-s.circulation.oxygenDelivery);s.metabolism.oxygenDebt=cl(s.metabolism.oxygenDebt+(shortage*.09-s.metabolism.oxygenDebt*.018)*dt);s.metabolism.availableEnergy=cl((s.body==null?1:s.body.energy/100.0)*(1-s.metabolism.oxygenDebt*.55));s.metabolism.metabolicHeat=cl(.1+s.metabolism.demand*.72);if(s.musculoskeletal!=null){double supply=.35+.65*s.metabolism.availableEnergy*s.circulation.oxygenDelivery;s.musculoskeletal.legForceCapacity=Math.max(.24,s.musculoskeletal.legForceCapacity*supply);s.musculoskeletal.coreForceCapacity=Math.max(.28,s.musculoskeletal.coreForceCapacity*(.45+.55*supply));}}
 private static double follow(double v,double t,double dt,double tau){double k=1-Math.exp(-dt/Math.max(.1,tau));return v+(t-v)*k;}private static double cl(double v){return Math.max(0,Math.min(1,v));}}
